//! Generated by the i18n verification harness: 200 catalog keys looked up
//! through `t!` and `t_rich!`. Prints one JSON line per (locale, sample).

use t3code_web::i18n::{Locale, RichText, runtime::activate_locale_blocking, t, t_rich};

type Sample = (usize, &'static str, Box<dyn Fn() -> String>);

fn rich(text: RichText) -> String {
    let segments: Vec<(String, Option<String>)> =
        text.segments.iter().map(|s| (s.text.to_string(), s.tag.as_ref().map(|t| t.to_string()))).collect();
    serde_json::to_string(&segments).unwrap()
}

