fn main() {
    let samples = samples();
    for locale in Locale::ALL {
        activate_locale_blocking(locale);
        for (id, kind, run) in &samples {
            let got = run();
            println!("{}", serde_json::json!({ "locale": locale.tag(), "id": id, "kind": kind, "got": got }));
        }
    }
}
